CREATE TABLE workspace(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL);
CREATE TABLE app_user(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspace, username text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','operator','reviewer','reader')), active boolean NOT NULL DEFAULT true, session_version integer NOT NULL DEFAULT 1);
CREATE TABLE permission(role text NOT NULL, action text NOT NULL, PRIMARY KEY(role,action));
INSERT INTO permission SELECT r,a FROM unnest(ARRAY['admin','operator','reviewer','reader'])r CROSS JOIN unnest(ARRAY['read'])a;
INSERT INTO permission SELECT r,a FROM unnest(ARRAY['admin','operator','reviewer'])r CROSS JOIN unnest(ARRAY['create','edit','import','withdraw'])a;
INSERT INTO permission SELECT r,a FROM unnest(ARRAY['admin','reviewer'])r CROSS JOIN unnest(ARRAY['review','export'])a;
INSERT INTO permission VALUES('admin','admin');
CREATE TABLE company_group(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspace,name text NOT NULL,version integer NOT NULL DEFAULT 1,active boolean NOT NULL DEFAULT true, UNIQUE(id,workspace_id));
CREATE TABLE company(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspace,group_id uuid,name text NOT NULL CHECK(length(trim(name))>0),industry text,address text,website text,status text NOT NULL DEFAULT 'NeedsReview',version integer NOT NULL DEFAULT 1,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,workspace_id),FOREIGN KEY(group_id,workspace_id) REFERENCES company_group(id,workspace_id));
CREATE INDEX company_search ON company(workspace_id,lower(name));
CREATE TABLE branch(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspace,company_id uuid NOT NULL,name text NOT NULL,address text,version integer NOT NULL DEFAULT 1,active boolean NOT NULL DEFAULT true,UNIQUE(id,company_id,workspace_id),FOREIGN KEY(company_id,workspace_id) REFERENCES company(id,workspace_id));
CREATE TABLE contact(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspace,name text NOT NULL,version integer NOT NULL DEFAULT 1,active boolean NOT NULL DEFAULT true,UNIQUE(id,workspace_id));
CREATE TABLE contact_company_role(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspace,company_id uuid NOT NULL,contact_id uuid NOT NULL,branch_id uuid,designation text,normalized_role text,department text,valid_from date NOT NULL DEFAULT current_date,valid_to date,version integer NOT NULL DEFAULT 1,active boolean NOT NULL DEFAULT true,CHECK(valid_to IS NULL OR valid_to>=valid_from),FOREIGN KEY(company_id,workspace_id) REFERENCES company(id,workspace_id),FOREIGN KEY(contact_id,workspace_id) REFERENCES contact(id,workspace_id),FOREIGN KEY(branch_id,company_id,workspace_id) REFERENCES branch(id,company_id,workspace_id));
CREATE TABLE channel_endpoint(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspace,channel text NOT NULL CHECK(channel IN ('Email','Phone','WhatsApp','Website','Social')),raw_value text NOT NULL,normalized_value text NOT NULL,verification text NOT NULL DEFAULT 'Unverified',reachability text NOT NULL DEFAULT 'Unknown',version integer NOT NULL DEFAULT 1,active boolean NOT NULL DEFAULT true,UNIQUE(workspace_id,channel,normalized_value),UNIQUE(id,workspace_id));
CREATE TABLE endpoint_association(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspace,endpoint_id uuid NOT NULL,company_id uuid NOT NULL,contact_id uuid,version integer NOT NULL DEFAULT 1,active boolean NOT NULL DEFAULT true,FOREIGN KEY(endpoint_id,workspace_id) REFERENCES channel_endpoint(id,workspace_id),FOREIGN KEY(company_id,workspace_id) REFERENCES company(id,workspace_id),FOREIGN KEY(contact_id,workspace_id) REFERENCES contact(id,workspace_id));
CREATE UNIQUE INDEX association_unique ON endpoint_association(endpoint_id,company_id,COALESCE(contact_id,'00000000-0000-0000-0000-000000000000'::uuid)) WHERE active;
CREATE TABLE source(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspace,type text NOT NULL,reference text NOT NULL,file_path text,collected_at timestamptz NOT NULL DEFAULT now(),actor_id uuid NOT NULL REFERENCES app_user);
CREATE TABLE field_observation(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspace,entity_type text NOT NULL,entity_id uuid NOT NULL,field text NOT NULL,raw_value text,normalized_value text,knowledge_status text NOT NULL DEFAULT 'KNOWN',source_id uuid NOT NULL REFERENCES source,sheet text,row_number integer,actor_id uuid NOT NULL REFERENCES app_user,collected_at timestamptz NOT NULL DEFAULT now(),last_checked timestamptz,verification text NOT NULL DEFAULT 'Unverified',selected boolean NOT NULL DEFAULT true);
CREATE INDEX observation_entity ON field_observation(workspace_id,entity_id);
CREATE TABLE verification_decision(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspace,observation_id uuid NOT NULL REFERENCES field_observation,reviewer_id uuid NOT NULL REFERENCES app_user,evidence text NOT NULL CHECK(length(trim(evidence))>0),decision text NOT NULL CHECK(decision IN ('Verified','Rejected')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE consent_event(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspace,endpoint_id uuid NOT NULL,contact_id uuid,purpose text NOT NULL,status text NOT NULL CHECK(status IN ('Unknown','OptedIn','OptedOut')),evidence text,actor_id uuid NOT NULL REFERENCES app_user,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(endpoint_id,workspace_id) REFERENCES channel_endpoint(id,workspace_id),FOREIGN KEY(contact_id,workspace_id) REFERENCES contact(id,workspace_id));
CREATE TABLE suppression_rule(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspace,endpoint_id uuid NOT NULL,purpose text NOT NULL,active boolean NOT NULL DEFAULT true,event_id uuid NOT NULL REFERENCES consent_event,UNIQUE(workspace_id,endpoint_id,purpose));
CREATE TABLE audit_event(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspace,actor_id uuid REFERENCES app_user,action text NOT NULL,resource_type text NOT NULL,resource_id text,resource_version integer,result text NOT NULL DEFAULT 'Success',change_ref jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION protect_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit events are append only'; END $$;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_event FOR EACH ROW EXECUTE FUNCTION protect_audit();
CREATE TABLE edit_conflict(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspace,entity_type text NOT NULL,entity_id uuid NOT NULL,current_value jsonb NOT NULL,proposed_value jsonb NOT NULL,actor_id uuid NOT NULL REFERENCES app_user,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE import_batch(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspace,actor_id uuid NOT NULL REFERENCES app_user,source_id uuid NOT NULL REFERENCES source,file_hash text NOT NULL,sheet text,mapping jsonb,mapping_version integer NOT NULL DEFAULT 0,state text NOT NULL DEFAULT 'Uploaded',fingerprint text,counts jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,fingerprint));
CREATE TABLE import_row(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL REFERENCES import_batch,row_number integer NOT NULL,data jsonb NOT NULL,raw_data jsonb NOT NULL,status text NOT NULL,reason text,company_id uuid,UNIQUE(batch_id,row_number));
CREATE TABLE import_effect(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL REFERENCES import_batch,row_id uuid REFERENCES import_row,entity_type text NOT NULL,entity_id uuid NOT NULL,version integer NOT NULL,before_value jsonb,after_value jsonb,undone boolean NOT NULL DEFAULT false,conflict text);
CREATE TABLE source_identity(workspace_id uuid NOT NULL REFERENCES workspace,namespace text NOT NULL,source_key text NOT NULL,company_id uuid NOT NULL,PRIMARY KEY(workspace_id,namespace,source_key),FOREIGN KEY(company_id,workspace_id) REFERENCES company(id,workspace_id));
CREATE TABLE job(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspace,batch_id uuid NOT NULL REFERENCES import_batch,kind text NOT NULL CHECK(kind IN ('commit','rollback')),state text NOT NULL DEFAULT 'Queued',attempts integer NOT NULL DEFAULT 0,error text,created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz);
CREATE UNIQUE INDEX active_batch_job ON job(batch_id,kind) WHERE state IN ('Queued','Running');
CREATE TABLE mutation_key(workspace_id uuid NOT NULL REFERENCES workspace,key text NOT NULL,hash text NOT NULL,response jsonb NOT NULL,PRIMARY KEY(workspace_id,key));
CREATE TABLE session(sid varchar PRIMARY KEY,sess json NOT NULL,expire timestamp NOT NULL);
CREATE INDEX session_expire ON session(expire);
